    integer errors = 0, checks = 0;
    task check(input [8*48-1:0] name, input [31:0] got, input [31:0] exp);
        begin
            checks = checks + 1;
            if (got !== exp) begin
                errors = errors + 1;
                $display("FAIL %0s: got %h expected %h", name, got, exp);
            end
        end
    endtask
    task axi_write(input [31:0] adr, input [31:0] dat, input [3:0] stb);
        begin
            @(posedge clk); awaddr <= adr; wdata <= dat; wstrb <= stb;
            awvalid <= 1; wvalid <= 1; bready <= 1;
            @(posedge clk); while (!awready) @(posedge clk);
            awvalid <= 0; wvalid <= 0;
            while (!bvalid) @(posedge clk);
            @(posedge clk); bready <= 0;
        end
    endtask
    task axi_read(input [31:0] adr, output [31:0] dat);
        begin
            @(posedge clk); araddr <= adr; arvalid <= 1; rready <= 1;
            @(posedge clk); while (!arready) @(posedge clk);
            arvalid <= 0;
            while (!rvalid) @(posedge clk);
            dat = rdata; @(posedge clk); rready <= 0;
        end
    endtask

